(function () {
  'use strict';
  function start() {
    const hero = document.querySelector('.b4y-home-video');
    if (!hero) return;
    const updateHeader = function () {
      document.body.classList.toggle('b4y-home-scrolled', window.scrollY > 110);
    };
    updateHeader();
    window.addEventListener('scroll', updateHeader, { passive: true });
    const media = document.querySelector('.b4y-home-video-element');
    if (media) {
      media.muted = true;
      const playing = media.play();
      if (playing && typeof playing.catch === 'function') playing.catch(function () {});
    }
    const texts = window.B4Y_HOME_STRINGS || {};
    let strings = window.innerWidth < 992 ? texts.mobile : texts.desktop;
    if (!Array.isArray(strings) || !strings.length) strings = texts.desktop || [];
    if (window.Typed && strings.length) {
      new window.Typed('#b4y-home-typed', {
        strings: strings,
        typeSpeed: 50,
        backDelay: 3000,
        startDelay: 1000,
        loop: true,
        contentType: 'html'
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
}());

/* Lightweight replacements for original Joomla AOS / Owl section behaviors.
   Only home sections are touched; video + Typed.js continue unchanged. */
(function(){'use strict';function init(){
 const root=document.querySelector('main.b4y-home-original');if(!root)return;
 if('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches){
   const observer=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('b4y-visible-motion');observer.unobserve(e.target)}})},{threshold:.08});
   root.querySelectorAll('[data-aos]').forEach(e=>{e.classList.add('b4y-initial-motion');observer.observe(e)});
 }
 root.querySelectorAll('.owl-carousel').forEach(car=>{
   const slides=Array.from(car.children).filter(x=>x.nodeType===1);
   if(slides.length<2)return;
   car.setAttribute('tabindex','0');car.setAttribute('role','region');car.setAttribute('aria-label','Karuzela Building4you');
   car.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){car.scrollBy({left:300,behavior:'smooth'})}if(e.key==='ArrowLeft'){car.scrollBy({left:-300,behavior:'smooth'})}});
 });
 root.querySelectorAll('[data-to]').forEach(el=>{
   const value=Number(el.getAttribute('data-to'));if(!Number.isFinite(value)||value<0)return;
   el.textContent=new Intl.NumberFormat('pl-PL').format(value);
 });
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();}());

(function(){'use strict';function init(){
 var track=document.querySelector('.b4y-home-project-track');if(!track)return;
 var prev=document.querySelector('.b4y-projects-prev');
 var next=document.querySelector('.b4y-projects-next');
 function move(direction){var card=track.querySelector('.b4y-rebuilt-project-card');
  var step=card?card.getBoundingClientRect().width+15:350;
  track.scrollBy({left:step*direction,behavior:'smooth'});}
 if(prev)prev.addEventListener('click',function(){move(-1)});
 if(next)next.addEventListener('click',function(){move(1)});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();

